Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int MOD = 1000000007;

int n;
int totalStates;
int bitsCount[250], positionMap[250];
int f[10][250];
vector<int> layerSets[10];
map<pair<int, long long>, int> cacheMap;

int fastPow(int base, int power) {
    int result = 1;
    while (power > 0) {
        if (power & 1) result = (long long)result * base % MOD;
        base = (long long)base * base % MOD;
        power >>= 1;
    }
    return result;
}

int recurseDP(int layer, long long mask) {
    if (mask == 0) return 0;
    if (layer == n) return 1;
    auto key = make_pair(layer, mask);
    if (cacheMap.count(key)) return cacheMap[key];

    totalStates++;
    int total = 0;
    for (int subsetMask = 1; subsetMask <= (1 << n) - 1; ++subsetMask) {
        long long next_mask = 0;
        for (size_t k = 0; k < layerSets[layer].size(); ++k) {
            if (!(mask & (1LL << k))) continue;
            int prevVal = layerSets[layer][k];
            for (int l = 0; l < n; ++l) {
                if ((subsetMask & (1 << l)) && !(prevVal & (1 << l))) {
                    next_mask |= 1LL << positionMap[prevVal | (1 << l)];
                }
            }
        }
        total = (total + (long long)f[layer][subsetMask] * recurseDP(layer + 1, next_mask)) % MOD;
    }
    cacheMap[key] = total;
    return total;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n;
    int inv100 = fastPow(100, MOD - 2);
    for (int i = 0; i < n; ++i) {
        f[i][0] = 1;
        for (int j = 0; j < n; ++j) {
            int P;
            cin >> P;
            int p1 = (long long)P * inv100 % MOD;
            int p0 = (MOD + 1 - p1) % MOD;
            for (int k = 0; k < (1 << j); ++k) {
                f[i][k | (1 << j)] = (long long)f[i][k] * p1 % MOD;
                f[i][k] = (long long)f[i][k] * p0 % MOD;
            }
        }
    }
    for (int i = 0; i < (1 << n); ++i) {
        bitsCount[i] = __builtin_popcount(i);
    }
    for (int i = 0; i < (1 << n); ++i) {
        layerSets[bitsCount[i]].push_back(i);
        positionMap[i] = (int)layerSets[bitsCount[i]].size() - 1;
    }
    cout << recurseDP(0, 1LL) << "\n";
    return 0;
}
